create extension if not exists pgcrypto;

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default 'Food friend', avatar_url text, created_at timestamptz not null default now());
create table public.groups (id uuid primary key default gen_random_uuid(), name text not null, join_code text not null unique check (join_code ~ '^[A-HJ-NP-Z2-9]{6}$'), created_by uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.group_members (group_id uuid not null references public.groups(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null default 'member' check (role in ('owner','member')), joined_at timestamptz not null default now(), primary key (group_id, user_id));
create table public.places (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, google_place_id text not null, name text not null, formatted_address text, latitude double precision, longitude double precision, price_level integer, cuisine text, website text, google_maps_url text, status text not null default 'Want to try' check (status in ('Been','Want to try')), pinned boolean not null default false, created_by uuid not null references auth.users(id), created_at timestamptz not null default now(), unique(group_id, google_place_id));
create table public.place_ratings (place_id uuid not null references public.places(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, score integer not null check (score between 1 and 5), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key (place_id, user_id));
create table public.dishes (id uuid primary key default gen_random_uuid(), place_id uuid not null references public.places(id) on delete cascade, name text not null, price numeric(10,2), description text, is_ai_suggestion boolean not null default false, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.dish_ratings (dish_id uuid not null references public.dishes(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, score integer not null check (score between 1 and 5), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key (dish_id, user_id));
create table public.lists (id uuid primary key default gen_random_uuid(), group_id uuid not null references public.groups(id) on delete cascade, name text not null, emoji text not null default '♡', created_by uuid not null references auth.users(id), created_at timestamptz not null default now());
create table public.list_places (list_id uuid not null references public.lists(id) on delete cascade, place_id uuid not null references public.places(id) on delete cascade, added_by uuid not null references auth.users(id), created_at timestamptz not null default now(), primary key (list_id, place_id));

create or replace function public.is_group_member(target_group uuid) returns boolean language sql stable security invoker set search_path = public as $$ select exists (select 1 from public.group_members where group_id = target_group and user_id = (select auth.uid())); $$;
create or replace function public.place_group(target_place uuid) returns uuid language sql stable security invoker set search_path = public as $$ select group_id from public.places where id = target_place; $$;
create or replace function public.dish_group(target_dish uuid) returns uuid language sql stable security invoker set search_path = public as $$ select p.group_id from public.dishes d join public.places p on p.id = d.place_id where d.id = target_dish; $$;

alter table public.profiles enable row level security; alter table public.groups enable row level security; alter table public.group_members enable row level security; alter table public.places enable row level security; alter table public.place_ratings enable row level security; alter table public.dishes enable row level security; alter table public.dish_ratings enable row level security; alter table public.lists enable row level security; alter table public.list_places enable row level security;

create policy profiles_read on public.profiles for select to authenticated using (id = (select auth.uid()) or exists (select 1 from public.group_members gm join public.group_members me on me.group_id = gm.group_id where gm.user_id = profiles.id and me.user_id = (select auth.uid())));
create policy profiles_insert on public.profiles for insert to authenticated with check (id = (select auth.uid())); create policy profiles_update on public.profiles for update to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
create policy groups_read on public.groups for select to authenticated using (public.is_group_member(id)); create policy groups_create on public.groups for insert to authenticated with check (created_by = (select auth.uid())); create policy groups_update on public.groups for update to authenticated using (created_by = (select auth.uid())) with check (created_by = (select auth.uid())); create policy groups_delete on public.groups for delete to authenticated using (created_by = (select auth.uid()));
create policy members_read on public.group_members for select to authenticated using (public.is_group_member(group_id)); create policy members_join on public.group_members for insert to authenticated with check (user_id = (select auth.uid()) and exists (select 1 from public.groups g where g.id = group_id)); create policy members_leave on public.group_members for delete to authenticated using (user_id = (select auth.uid()));
create policy places_read on public.places for select to authenticated using (public.is_group_member(group_id)); create policy places_write on public.places for insert to authenticated with check (public.is_group_member(group_id) and created_by = (select auth.uid())); create policy places_update on public.places for update to authenticated using (public.is_group_member(group_id)) with check (public.is_group_member(group_id)); create policy places_delete on public.places for delete to authenticated using (public.is_group_member(group_id) and created_by = (select auth.uid()));
create policy place_ratings_read on public.place_ratings for select to authenticated using (public.is_group_member(public.place_group(place_id))); create policy place_ratings_write on public.place_ratings for insert to authenticated with check (user_id = (select auth.uid()) and public.is_group_member(public.place_group(place_id))); create policy place_ratings_update on public.place_ratings for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid())); create policy place_ratings_delete on public.place_ratings for delete to authenticated using (user_id = (select auth.uid()));
create policy dishes_read on public.dishes for select to authenticated using (public.is_group_member(public.place_group(place_id))); create policy dishes_write on public.dishes for insert to authenticated with check (public.is_group_member(public.place_group(place_id)) and (created_by is null or created_by = (select auth.uid()))); create policy dishes_update on public.dishes for update to authenticated using (public.is_group_member(public.place_group(place_id))); create policy dishes_delete on public.dishes for delete to authenticated using (public.is_group_member(public.place_group(place_id)) and (created_by = (select auth.uid()) or created_by is null));
create policy dish_ratings_read on public.dish_ratings for select to authenticated using (public.is_group_member(public.dish_group(dish_id))); create policy dish_ratings_write on public.dish_ratings for insert to authenticated with check (user_id = (select auth.uid()) and public.is_group_member(public.dish_group(dish_id))); create policy dish_ratings_update on public.dish_ratings for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid())); create policy dish_ratings_delete on public.dish_ratings for delete to authenticated using (user_id = (select auth.uid()));
create policy lists_read on public.lists for select to authenticated using (public.is_group_member(group_id)); create policy lists_write on public.lists for insert to authenticated with check (public.is_group_member(group_id) and created_by = (select auth.uid())); create policy lists_update on public.lists for update to authenticated using (public.is_group_member(group_id)); create policy lists_delete on public.lists for delete to authenticated using (created_by = (select auth.uid()));
create policy list_places_read on public.list_places for select to authenticated using (exists (select 1 from public.lists l where l.id = list_id and public.is_group_member(l.group_id))); create policy list_places_write on public.list_places for insert to authenticated with check (added_by = (select auth.uid()) and exists (select 1 from public.lists l join public.places p on p.group_id = l.group_id where l.id = list_id and p.id = place_id and public.is_group_member(l.group_id))); create policy list_places_delete on public.list_places for delete to authenticated using (added_by = (select auth.uid()));

create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles(id, display_name, avatar_url) values (new.id, coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email, '@', 1)), new.raw_user_meta_data->>'avatar_url') on conflict (id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
